<script setup lang="ts">
import { ref } from "vue";import{ElMessageBox}from"element-plus";import{api}from"../utils/api";
const year=ref(String(new Date().getFullYear()));const preview=ref<any>();const accounts=ref<any[]>([]);const profitAccountId=ref<number | "">("");const result=ref<any>();async function load(){preview.value=await api.get(`/year-end-closings/${year.value}/preview`);if(!accounts.value.length)accounts.value=await api.get<any[]>("/accounts");}async function close(){result.value=await api.post(`/year-end-closings/${year.value}`,{profitAccountId:profitAccountId.value});}async function cancel(){const {value}=await ElMessageBox.prompt("请输入撤销原因","撤销年度结转",{inputPattern:/\S+/,inputErrorMessage:"撤销原因不能为空"});await api.post(`/year-end-closings/${year.value}/cancel`,{reason:value});result.value=null;await load();}
</script>
<template><div class="page-grid"><section class="page-heading"><div><h2>年末结转</h2><p>预览年度已记账损益数据，正式结转前需完成全部月末关账。</p></div></section><el-card shadow="never"><div class="toolbar"><el-input v-model="year" style="width:120px"/><el-select v-model="profitAccountId" filterable placeholder="本年利润科目" style="width:220px"><el-option v-for="a in accounts" :key="a.id" :label="`${a.code} ${a.name}`" :value="a.id"/></el-select><el-button @click="load">试运行预览</el-button><el-button type="primary" :disabled="!preview || !profitAccountId" @click="close">正式结转</el-button><el-button v-if="result" type="danger" @click="cancel">撤销结转</el-button></div></el-card><el-card v-if="preview" shadow="never"><el-descriptions :column="4"><el-descriptions-item label="收入">{{preview.revenueAmount}}</el-descriptions-item><el-descriptions-item label="成本">{{preview.costAmount}}</el-descriptions-item><el-descriptions-item label="费用">{{preview.expenseAmount}}</el-descriptions-item><el-descriptions-item label="本年利润">{{preview.netProfit}}</el-descriptions-item></el-descriptions><el-table table-layout="auto" :data="preview.lines" stripe><el-table-column prop="code" label="科目编码"/><el-table-column prop="name" label="科目名称"/><el-table-column prop="kind" label="类型"/><el-table-column prop="amount" label="结转金额"/></el-table></el-card></div></template>
